style.css:
/* General background and text styling for all websites */
* {
    background-color: rgb(18, 18, 18) !important; /* Darkest color */
    color: rgb(130, 133, 138) !important;        /* Text color */
    border-color: rgb(32, 34, 37) !important;    /* Slightly darker color */
}

/* Links */
a {
    color: rgb(130, 133, 138) !important;        /* Text color */
    text-decoration: none;
}

a:hover {
    color: rgb(205, 214, 244) !important;       /* Slightly brighter link hover */
}

/* Buttons */
button, input[type="button"], input[type="submit"] {
    background-color: rgb(32, 34, 37) !important; /* Button background */
    color: rgb(130, 133, 138) !important;        /* Button text */
    border: 1px solid rgb(46, 51, 56) !important; /* Border color */
}

button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    background-color: rgb(46, 51, 56) !important; /* Slightly lighter on hover */
}

/* Form inputs */
input, textarea, select {
    background-color: rgb(18, 18, 18) !important; /* Input background */
    color: rgb(130, 133, 138) !important;        /* Input text */
    border: 1px solid rgb(32, 34, 37) !important; /* Input border */
}

/* Navbar styling */
nav {
    background-color: rgb(32, 34, 37) !important; /* Navbar background */
    color: rgb(130, 133, 138) !important;        /* Navbar text */
}

/* Table styling */
table {
    background-color: rgb(18, 18, 18) !important; /* Table background */
    border-collapse: collapse;
    color: rgb(130, 133, 138) !important;        /* Table text */
}

th, td {
    border: 1px solid rgb(32, 34, 37) !important; /* Table cell border */
    padding: 8px;
}

/* Highlighted elements */
::selection {
    background-color: rgb(46, 51, 56) !important; /* Highlight background */
    color: rgb(130, 133, 138) !important;        /* Highlight text */
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 12px;
    background-color: rgb(18, 18, 18);           /* Scrollbar background */
}

::-webkit-scrollbar-thumb {
    background-color: rgb(46, 51, 56);           /* Scrollbar thumb */
    border-radius: 6px;
}
